<script setup>
import { computed,onBeforeUnmount,ref,watch } from 'vue'
import { can } from '../../permissions.js'
import { createClientId } from '../../clientId.js'
import { maintenanceAll,maintenanceRead,maintenanceWrite,maintenanceExport,maintenanceAttachment } from '../../maintenance/api.js'
import { maintenanceTime,stateLabel,verificationLabel,metricCells,hours,money,durationLabel,unwrapOutputs,reviewStates,runIsActive } from '../../maintenance/helpers.js'
const props=defineProps({run:Object,scenario:Object,devices:Array,assets:Array,investment:Boolean})
const emit=defineEmits(['navigate','refresh','snapshot'])
const loading=ref(false),error=ref(''),snapshot=ref(null),rows=ref([]),findings=ref([]),evidence=ref([]),reviews=ref([]),busy=ref(false),downloading=ref(false),reviewResult=ref('OBSERVE'),explanation=ref(''),reviewKey=ref(''),reviewError=ref(''),jobs=ref([]),jobId=ref(''),aiBusy=ref(false),aiError=ref(''),aiKey=ref(''),useKnowledge=ref(false),detail=ref(null),dialog=ref(false)
let generation=0,disposed=false,timer=0
const resource=computed(()=>props.investment?'investment-evaluations':'maintenance-observations'),aiResource=computed(()=>props.investment?'investment-scenarios':'maintenance-observations'),aiParent=computed(()=>props.investment?props.scenario?.resourceId:props.run?.id),activeAI=computed(()=>jobs.value.find(row=>row.id===jobId.value)||jobs.value[0]),interpretation=computed(()=>activeAI.value?.interpretation||{}),comparison=computed(()=>snapshot.value?.statistics||{}),supplement=computed(()=>comparison.value.supplement||{}),aiSections=computed(()=>props.investment?[['priorityExplanations','已有优先因素'],['decisionConsiderations','人工决定考虑'],['limitations','限制']]:[['observedChanges','观察到的变化'],['confounders','混杂因素'],['verificationSuggestions','后续核验建议'],['limitations','限制']])
const deviceName=id=>props.devices.find(d=>d.id===id)?.name||id
const assetName=id=>props.assets.find(a=>a.id===id)?.body.name||'固定历史实物版本'
function stopPolling(){clearTimeout(timer);timer=0}
async function loadAI(){const token=generation,id=aiParent.value,runId=props.run?.id;if(!id||!snapshot.value||!can('GET /api/v1/'+aiResource.value+'/:id/ai-jobs'))return;try{const v=await maintenanceRead(aiResource.value,id,'ai-jobs',{runId});if(token!==generation||disposed)return;jobs.value=v.items||[];if(!jobId.value||!jobs.value.some(j=>j.id===jobId.value))jobId.value=jobs.value[0]?.id||'';stopPolling();if(jobs.value.some(j=>['QUEUED','RUNNING'].includes(j.status)))timer=setTimeout(loadAI,1800)}catch(cause){if(token===generation){aiError.value=cause.message;jobs.value=[]}}}
async function load(){const token=++generation;stopPolling();snapshot.value=null;rows.value=[];findings.value=[];evidence.value=[];reviews.value=[];jobs.value=[];jobId.value='';detail.value=null;dialog.value=false;error.value='';aiError.value='';reviewError.value='';reviewKey.value=createClientId();aiKey.value=createClientId();if(!props.run||runIsActive(props.run))return;loading.value=true;try{const id=props.run.id,r=resource.value;const v=await Promise.all([maintenanceRead(r,id,'snapshot'),maintenanceAll(r,id,props.investment?'investment-priorities':'observations'),maintenanceAll(r,id,'findings'),maintenanceAll(r,id,'evidence'),maintenanceAll(r,id,'reviews')]);if(token!==generation||disposed)return;[snapshot.value,rows.value,findings.value,evidence.value,reviews.value]=[v[0],unwrapOutputs(v[1].items),unwrapOutputs(v[2].items),v[3].items||[],v[4].items||[]];emit('snapshot',snapshot.value);await loadAI()}catch(cause){if(token===generation){error.value=[403,404].includes(cause.status)?'此固定版本不存在或当前权限已无法读取；请核对范围与资金权限。':cause.message;snapshot.value=null;rows.value=[];evidence.value=[];reviews.value=[];jobs.value=[];emit('snapshot',null)}}finally{if(token===generation)loading.value=false}}
async function review(){if(busy.value||!snapshot.value)return;busy.value=true;reviewError.value='';const token=generation;try{if(!explanation.value.trim())throw Error('请记录人工核实依据');await maintenanceWrite(resource.value,props.run.id,'reviews',{expectedVersion:props.run.version,snapshotVersion:snapshot.value.version,factsHash:snapshot.value.factsHash,result:reviewResult.value,explanation:explanation.value.trim(),idempotencyKey:reviewKey.value});if(token!==generation||disposed)return;explanation.value='';emit('refresh');await load()}catch(cause){if(token===generation)reviewError.value=cause.status===409?'任务或快照版本已变化，请重新读取固定事实。':cause.message}finally{if(token===generation)busy.value=false}}
async function runAI(){if(aiBusy.value||!snapshot.value)return;const token=generation;aiBusy.value=true;aiError.value='';try{const job=await maintenanceWrite(aiResource.value,aiParent.value,'ai-jobs?'+new URLSearchParams({runId:props.run.id}),{expectedVersion:props.run.version,idempotencyKey:aiKey.value,useKnowledge:useKnowledge.value,reinterpret:!!jobs.value.length});if(token!==generation||disposed)return;jobId.value=job.id;aiKey.value=createClientId();await loadAI()}catch(cause){if(token===generation)aiError.value=cause.message}finally{if(token===generation)aiBusy.value=false}}
async function stopAI(){if(!activeAI.value||aiBusy.value)return;aiBusy.value=true;try{await maintenanceWrite(aiResource.value,aiParent.value,'ai-jobs/'+encodeURIComponent(activeAI.value.id)+'/stop',{expectedVersion:activeAI.value.version});await loadAI()}catch(cause){aiError.value=cause.message}finally{aiBusy.value=false}}
async function exportReport(){if(downloading.value)return;downloading.value=true;try{await maintenanceExport(resource.value,props.run.id)}catch(cause){error.value=cause.message}finally{downloading.value=false}}
function inspect(row){detail.value=row;dialog.value=true}
function fact(id){const row=evidence.value.find(e=>e.id===id)||rows.value.find(e=>e.id===id)||findings.value.find(e=>e.id===id);if(row)inspect(row);else{detail.value={id,summary:{description:'该事实引用属于固定快照；当前代表证据中没有原始详情。'}};dialog.value=true}}
async function download(ev){try{await maintenanceAttachment(ev.sourceId,ev.summary?.name||ev.summary?.description)}catch(cause){error.value=cause.message}}
watch(()=>[props.run?.id,props.run?.version,props.scenario?.resourceId],load,{immediate:true});onBeforeUnmount(()=>{disposed=true;generation++;stopPolling()})
</script>
<template><section class="maintenance-stack"><ui-skeleton v-if="loading" :rows="5"/><ui-alert v-if="error" :title="error" type="error" :closable="false"><ui-button size="small" @click="load">重新读取固定版本</ui-button></ui-alert><template v-if="snapshot"><article class="maintenance-card"><div class="maintenance-toolbar"><h3>{{investment?'固定透明排序':'固定前后变化观察'}}</h3><ui-button v-if="can('GET /api/v1/'+resource+'/:id/export')" size="small" :loading="downloading" @click="exportReport">下载固定报告</ui-button></div><p class="maintenance-meta">冻结资料截至 {{maintenanceTime(snapshot.dataCutoff)}} · 快照版本 {{snapshot.version}}<br>事实哈希 {{snapshot.factsHash}}<br>固定输入 {{snapshot.inputHashes?.join(' · ')}}</p><p class="maintenance-hint">{{investment?'排序及预算为透明试算，人工决定不表示采购完成。':'结果描述固定窗口与来源覆盖内的变化，准入不证明显著性或维修因果效果。'}}</p><ui-alert v-for="(text,i) in snapshot.limitations||[]" :key="i" :title="stateLabel(text)" type="warning" :closable="false"/></article>
<template v-if="!investment"><article class="maintenance-card"><h3>{{stateLabel(comparison.status)}} · 功能验收 {{verificationLabel(comparison.verification)}}</h3><p class="maintenance-meta">{{stateLabel(comparison.parameters?.comparisonType)}} · 固定前实物 {{assetName(comparison.parameters?.beforeAssetRevisionId)}} · 固定后实物 {{assetName(comparison.parameters?.afterAssetRevisionId)}}<br>比较准入固定版本 {{comparison.parameters?.admission?.version||'未配置，仅描述'}} · 实物年限 {{supplement.physicalAgeKnown?'有已登记投运依据':'未知，不使用平台注册日期'}}<br>前后工况 {{supplement.contextComparable?'有同口径依据':'未知或口径不同'}} · 前强度 {{supplement.beforeIntensity||'未知'}} · 后强度 {{supplement.afterIntensity||'未知'}}</p><ui-alert v-for="(reason,i) in comparison.confounders||[]" :key="i" :title="stateLabel(reason)" type="warning" :closable="false"/><p v-for="(reason,i) in comparison.limitations||[]" :key="i" class="maintenance-hint">{{stateLabel(reason)}}</p></article><div class="maintenance-grid"><article v-for="side in ['before','after']" :key="side" class="maintenance-card maintenance-stack" :data-maintenance-side="side"><h3>{{side==='before'?'维修前':'维修后'}}窗口</h3><p class="maintenance-meta">计划 {{maintenanceTime(comparison.parameters?.[side]?.start)}} 至 {{maintenanceTime(comparison.parameters?.[side]?.end)}}<br>实际观测 {{maintenanceTime(supplement[side==='before'?'observedBefore':'observedAfter']?.start)}} 至 {{maintenanceTime(supplement[side==='before'?'observedBefore':'observedAfter']?.end)}}</p><div class="maintenance-stats"><article v-for="cell in metricCells(comparison[side]||{})" :key="cell.label"><span class="maintenance-meta">{{cell.label}}</span><strong>{{cell.value}}</strong></article></div><h4>已确认排除区间</h4><p v-for="(ex,i) in comparison[side]?.exclusions||[]" :key="i" class="maintenance-meta">{{stateLabel(ex.kind)}} · {{maintenanceTime(ex.start)}} 至 {{maintenanceTime(ex.end)}} · 固定工况 {{ex.sourceRevisionId}}</p><p v-if="!comparison[side]?.exclusions?.length" class="maintenance-hint">无有依据的排除区间；设备离线始终留在有效分母。</p><p v-for="(text,i) in comparison[side]?.limitations||[]" :key="i" class="maintenance-hint">{{stateLabel(text)}}</p></article></div><article class="maintenance-card"><h3>再次出现、重复维护与固定数据质量</h3><p class="maintenance-meta">同类再次出现 {{supplement.firstRecurrenceEventAt?maintenanceTime(supplement.firstRecurrenceEventAt):'固定来源覆盖内未观察到，不代表零风险'}} · 间隔 {{supplement.recurrenceElapsedMs!=null?durationLabel(supplement.recurrenceElapsedMs):'未知'}}<br>重复维护 {{supplement.repeatedMaintenanceRecords?.length||0}} 条</p><ui-button v-for="q in supplement.qualitySnapshots||[]" :key="q.runId" text size="small" @click="emit('navigate','dataQuality',{runId:q.runId,deviceId:run.deviceIds?.[0]})">读取固定质量报告</ui-button><article v-for="(cost,i) in supplement.recordedActualCosts||[]" :key="i"><p class="maintenance-meta">已记录实际支出 {{cost.currency}} · 材料 {{money(cost.material)}} · 人工 {{money(cost.labor)}} · 外部服务 {{money(cost.externalService)}} · 工时 {{money(cost.laborHours)}}</p></article></article></template>
<article v-else class="maintenance-card maintenance-stack"><h3>分层优先理由与预算试算</h3><p class="maintenance-meta">策略 {{comparison.policyVersion}} · {{comparison.usesFinance?'资金权限固定版本':'不使用资金因素的版本'}} · 币种 {{comparison.currency}} · 预算 {{comparison.usesFinance?money(comparison.budget):'不纳入此版本'}}</p><div class="maintenance-table-scroll"><ui-table :data="rows" empty-text="固定方案暂无可展示候选。"><ui-table-column label="顺序 / 人工必需层" min-width="170"><template #default="{row}">{{row.rank>0?row.rank:'待补资料'}} · 层 {{row.candidate.requiredTier}}<p class="maintenance-meta">{{stateLabel(row.status)}}<br>{{row.candidate.tierBasis}}</p></template></ui-table-column><ui-table-column label="动作 / 已核实因素" min-width="250"><template #default="{row}">{{stateLabel(row.candidate.action)}} · {{assetName(row.candidate.assetRevisionId)}}<p class="maintenance-meta">功能缺陷 {{row.candidate.unresolvedVerifiedDefect?'有已核实且未解除缺陷':'无已核实未解除缺陷'}} · 人工重要性 {{row.candidate.importance}}<br>同口径故障率 {{row.candidate.confirmedFaultRate??'未知'}} 次/1000小时 · 已知离线 {{hours(row.candidate.knownOfflineMs)}}</p></template></ui-table-column><ui-table-column label="具体优先理由 / 约束" min-width="280"><template #default="{row}"><p v-for="(reason,i) in row.reasons" :key="i">{{stateLabel(reason)}}</p><p class="maintenance-meta">{{row.candidate.constraints?.join('；')}}</p></template></ui-table-column><ui-table-column v-if="comparison.usesFinance" label="报价 / 累计 / 缺口" min-width="240"><template #default="{row}">{{stateLabel(row.budgetStatus)}}<p class="maintenance-meta">报价 {{money(row.quote)}} · 累计 {{money(row.knownCumulativeQuote)}}<br>追加预算 {{money(row.budgetShortfall)}}<br>固定报价版本 {{row.quoteRevisionId||'未知'}}</p></template></ui-table-column></ui-table></div></article>
<article v-if="findings.length" class="maintenance-card maintenance-stack"><h3>固定发现与限制依据</h3><article v-for="row in findings" :key="row.id"><p>{{stateLabel(row.limitation||row.kind||row.status)}}</p><p v-for="(reason,i) in row.reasons||[]" :key="i" class="maintenance-meta">{{stateLabel(reason)}}</p><ui-button text size="small" @click="inspect(row)">核对发现依据</ui-button></article></article><article class="maintenance-card maintenance-stack"><h3>人工核实固定事实</h3><p v-for="r in reviews" :key="r.id" class="maintenance-meta">{{reviewStates[r.result]}} · {{r.reviewer}} · {{maintenanceTime(r.reviewedAt||r.createdAt)}}<br>{{r.explanation}}</p><ui-alert v-if="reviewError" :title="reviewError" type="error" :closable="false"/><ui-form v-if="can('POST /api/v1/'+resource+'/:id/reviews')" label-position="top" :disabled="busy"><ui-form-item label="人工核实状态" required><ui-select v-model="reviewResult"><ui-option v-for="(label,id) in reviewStates" :key="id" :value="id" :label="label"/></ui-select></ui-form-item><ui-form-item label="人工核实依据" required><ui-input v-model="explanation" type="textarea" :rows="3"/></ui-form-item><ui-button size="small" type="primary" :loading="busy" @click="review">保存独立人工核实</ui-button></ui-form><p class="maintenance-hint">人工核实独立保存，保留原固定指标与分母。</p></article>
<article class="maintenance-card maintenance-stack"><h3>固定来源与证据</h3><div class="maintenance-table-scroll"><table class="maintenance-native-table"><thead><tr><th>实际来源</th><th>覆盖与版本</th><th>读取时间</th></tr></thead><tbody><tr v-for="(source,i) in snapshot.sources||[]" :key="i"><td>{{stateLabel(source.source)}}</td><td>{{source.complete?'完整':'部分或未知'}} · {{source.version}}<br>{{maintenanceTime(source.start)}} 至 {{maintenanceTime(source.end)}}</td><td>{{maintenanceTime(source.readAt)}}</td></tr></tbody></table></div><ui-button v-for="ev in evidence" :key="ev.id" size="small" @click="inspect(ev)">{{stateLabel(ev.sourceKind)}} · {{deviceName(ev.deviceId)}} · 核对来源</ui-button><ui-empty v-if="!evidence.length" description="此固定版本没有代表证据，来源缺口以快照限制为准。"/></article>
<article class="maintenance-card maintenance-stack"><div class="maintenance-toolbar"><h3>AI {{investment?'投入理由整理':'变化解读'}}</h3><div v-if="can('POST /api/v1/'+aiResource+'/:id/ai-jobs')" class="maintenance-actions"><ui-checkbox v-model="useKnowledge" :disabled="aiBusy">使用已授权知识</ui-checkbox><ui-button size="small" :loading="aiBusy" :disabled="['QUEUED','RUNNING'].includes(activeAI?.status)" @click="runAI">{{activeAI?'重新解读':'开始解读'}}</ui-button><ui-button v-if="['QUEUED','RUNNING'].includes(activeAI?.status)" size="small" @click="stopAI">停止解读</ui-button></div></div><p class="maintenance-hint">点击后启动工作流，AI 独立保存版本。模型失败不影响验收、人工核实、决定与报告。</p><ui-alert v-if="aiError" :title="aiError" type="error" :closable="false"/><ui-select v-if="jobs.length" v-model="jobId"><ui-option v-for="job in jobs" :key="job.id" :value="job.id" :label="`${maintenanceTime(job.createdAt)} · ${stateLabel(job.status)}`"/></ui-select><template v-if="activeAI"><p>{{stateLabel(activeAI.status)}} · {{activeAI.model||'工作流配置模型'}}</p><p class="maintenance-meta">固定快照 {{activeAI.snapshotVersion}} · 实际提供事实 {{activeAI.factIds?.length||0}} 条 · {{activeAI.coverage?.summary||'读取范围以固定事实与受控工具记录为准'}}</p><ui-alert v-if="activeAI.error" :title="activeAI.error" type="warning" :closable="false"/><template v-if="activeAI.status==='SUCCEEDED'"><p>{{interpretation.summary}}</p><article v-for="[id,title] in aiSections" :key="id"><h4>{{title}}</h4><div v-for="(statement,i) in interpretation[id]||[]" :key="i"><p>{{statement.text}}</p><ui-button v-for="fid in statement.factIds||[]" :key="fid" text size="small" @click="fact(fid)">核对引用事实</ui-button></div></article></template></template><ui-empty v-else description="尚未主动生成 AI 解读。"/></article></template>
<ui-dialog v-model="dialog" title="核对固定事实与原始来源" width="min(850px,94vw)"><div v-if="detail" class="maintenance-dialog-body maintenance-stack"><p>{{stateLabel(detail.sourceKind||detail.status||detail.id)}} · {{deviceName(detail.deviceId)}}</p><p class="maintenance-meta">事件 {{maintenanceTime(detail.occurredAt)}} · 固定来源版本 {{detail.resourceVersion}}<br>{{detail.originalAvailability}}</p><p v-for="(reason,i) in detail.limitations||detail.reasons||[]" :key="i">{{stateLabel(reason)}}</p><p v-if="detail.summary?.description">{{detail.summary.description}}</p><p v-if="detail.summary?.revisionId" class="maintenance-meta">固定资料 {{detail.summary.revisionId}} · 内容哈希 {{detail.summary.hash}}</p><pre class="maintenance-meta">{{JSON.stringify(detail.summary||detail,null,2)}}</pre><ui-button v-if="detail.sourceKind==='ATTACHMENT'&&can('GET /api/v1/maintenance-attachments/:id')" size="small" @click="download(detail)">受权下载原件</ui-button><ui-button v-if="detail.rawMessageId&&can('menu:raw')" size="small" @click="emit('navigate','raw',{deviceId:detail.deviceId,messageId:detail.rawMessageId})">读取具体原始报文</ui-button></div><template #footer><ui-button @click="dialog=false">关闭</ui-button></template></ui-dialog></section></template>
